import re
from nltk import word_tokenize
from collections import Counter

def task_func(input_str):
    if input_str is None:
        return {}

    # Keep only alphanumeric characters and whitespace; replace everything else with spaces.
    cleaned = re.sub(r"[^A-Za-z0-9\s]", " ", input_str)
    cleaned = re.sub(r"\s+", " ", cleaned).strip()

    if not cleaned:
        return {}

    try:
        words = word_tokenize(cleaned)
    except LookupError:
        # Fallback if NLTK tokenizer data is unavailable.
        words = cleaned.split()

    words = [w.lower() for w in words if re.search(r"\w", w)]
    return dict(Counter(words))
